patch:
diff --git a/share/messages_to_error_log.txt b/share/messages_to_error_log.txt
index d0a58841ecb7..8730dc1d8a58 100644
--- a/share/messages_to_error_log.txt
+++ b/share/messages_to_error_log.txt
@@ -10890,6 +10890,12 @@ ER_IB_TABLESPACE_PATH_VALIDATION_SKIPPED
 ER_IB_CANNOT_UPGRADE_WITH_DISCARDED_TABLESPACES
   eng "Upgrade failed because database contains discarded tablespaces."

+ER_USERNAME_TRUNKATED
+  eng "The user name '%s' exceeds the maximum number of allowed characters %d and is trunkated."
+
+ER_HOSTNAME_TRUNKATED
+  eng "The host name '%s' exceeds the maximum number of allowed characters %d and is trunkated."
+
 # DO NOT add server-to-client messages here;
 # they go in messages_to_clients.txt
 # in the same directory as this file.
diff --git a/sql/set_var.cc b/sql/set_var.cc
index 0df8d8008097..2b60241f4582 100644
--- a/sql/set_var.cc
+++ b/sql/set_var.cc
@@ -392,16 +392,24 @@ bool sys_var::set_default(THD *thd, set_var *var) {

 void sys_var::set_user_host(THD *thd) {
   memset(user, 0, sizeof(user));
-  DBUG_ASSERT(thd->security_context()->user().length < sizeof(user));
-  /* set client user */
-  if (thd->security_context()->user().length > 0)
-    strncpy(user, thd->security_context()->user().str,
-            thd->security_context()->user().length);
   memset(host, 0, sizeof(host));
-  if (thd->security_context()->host().length > 0) {
-    int host_len =
-        min<size_t>(sizeof(host) - 1, thd->security_context()->host().length);
-    strncpy(host, thd->security_context()->host().str, host_len);
+  Security_context *sctx = thd->security_context();
+  bool truncated = false;
+  if (sctx->user().length > 0) {
+    truncated = set_and_truncate(user, thd->security_context()->user().str,
+                                 sizeof(user));
+    if (truncated) {
+      LogErr(WARNING_LEVEL, ER_USERNAME_TRUNKATED, sctx->user().str,
+             USERNAME_CHAR_LENGTH);
+    }
+  }
+  if (sctx->host().length > 0) {
+    truncated = set_and_truncate(host, thd->security_context()->host().str,
+                                 sizeof(host));
+    if (truncated) {
+      LogErr(WARNING_LEVEL, ER_HOSTNAME_TRUNKATED, sctx->host().str,
+             HOSTNAME_LENGTH);
+    }
   }
 }
